insert into public.courses (id, sort_order, title, description) values
  ('fundamentals', 1, 'Electronics fundamentals', 'Voltage, current, resistance, components and using a multimeter.'),
  ('power', 2, 'Smartphone power systems', 'Battery, charging, PMIC, rails and current-draw diagnosis.'),
  ('boot', 3, 'Boot sequence and startup', 'From power key press to the OS: what happens and in what order.'),
  ('clocks', 4, 'Clocks and reset', 'Crystals, oscillators, reset lines and why they stop a board booting.'),
  ('memory', 5, 'RAM and storage', 'LPDDR, eMMC, UFS, stacked packages and memory-related faults.'),
  ('buses', 6, 'SoC and peripheral communication', 'I²C, SPI, MIPI and how the SoC talks to everything else.'),
  ('platforms', 7, 'Platform-specific architecture', 'How MediaTek, Snapdragon, Exynos, UNISOC and Apple designs differ.'),
  ('diagnosis', 8, 'Practical fault diagnosis', 'A systematic workflow from symptom to verified repair.')
insert into public.lessons (id, course_id, slug, sort_order, title, summary, minutes, difficulty, status, objectives, blocks) values
  ('fundamentals/voltage-current-resistance', 'fundamentals', 'voltage-current-resistance', 1, 'Voltage, current and resistance', 'The three quantities behind every fault you will diagnose, and how Ohm''s law links them.', 10, 'beginner', 'published', array['Explain voltage, current and resistance in plain terms', 'Use Ohm''s law to work out one value from the other two', 'Explain why a short circuit draws high current and an open circuit draws none']::text[], '[{"type":"text","text":"Almost every phone fault, from a dead board to a camera that won''t open, comes down to three quantities: voltage, current and resistance. If you understand how they relate, measurements stop being random numbers and start telling you a story."},{"type":"heading","text":"Voltage: the push"},{"type":"text","text":"Voltage (measured in volts, V) is the difference in electrical pressure between two points. It is what pushes current through a circuit. A voltage is always measured between two points. On a phone board, that is usually between a test point and ground."},{"type":"heading","text":"Current: the flow"},{"type":"text","text":"Current (measured in amps, A) is how much electric charge flows past a point each second. Phone currents are often small, so you will see milliamps (mA): 1 A = 1000 mA."},{"type":"heading","text":"Resistance: the opposition"},{"type":"text","text":"Resistance (measured in ohms, Ω) is how strongly something opposes current. A thin, long path has more resistance than a short, thick one. Components such as resistors are made to have a specific resistance."},{"type":"callout","tone":"key","title":"Ohm''s law","text":"V = I × R. Rearranged, I = V ÷ R and R = V ÷ I. If you know any two values, you can work out the third."},{"type":"example","title":"Worked example (textbook numbers, not a phone measurement)","steps":["A 4 V supply is connected across a 2 Ω resistance.","Current I = V ÷ R = 4 ÷ 2 = 2 A.","Now imagine the resistance drops to 0.1 Ω, like a near-short. I = 4 ÷ 0.1 = 40 A, far more than the circuit is designed to carry."],"note":"In a real circuit, the supply''s current limit, the battery and the short''s actual resistance limit the current. The energy usually turns into heat at the shorted spot, which is why shorted parts get warm."},{"type":"heading","text":"Why this matters for repair"},{"type":"list","items":["A short circuit is a very low-resistance path, so current rises sharply. That is why a shorted capacitor heats up and why a bench power supply shows high current.","An open circuit (a broken track, cracked solder joint or torn flex) has very high resistance, so no current flows and the part beyond the break gets no power.","Power is P = V × I. The heat you feel at a fault is power being turned into heat at that spot."]},{"type":"diagram","diagram":"circuit-states","caption":"The same loop three ways. Normal: the load sets the current. Open: a break stops it. Short: a low-resistance path bypasses the load, current rises and the short heats up. Textbook symbols, not a phone circuit."},{"type":"callout","tone":"tip","title":"Ground is your reference","text":"Most measurements on a phone board are taken relative to ground. Shield frames and screw points are often grounded, but always confirm a ground point on the schematic or boardview for that model."}]'::jsonb),
  ('fundamentals/multimeter-basics', 'fundamentals', 'multimeter-basics', 2, 'Using a multimeter safely', 'Choose the right mode, measure voltage correctly, and avoid damaging the meter or the board.', 12, 'beginner', 'published', array['Choose the right multimeter mode for each test', 'Know which tests need the board powered and which need it unpowered', 'Measure a DC voltage step by step and record the conditions']::text[], '[{"type":"text","text":"A digital multimeter is your main diagnostic tool. Used well, it tells you whether power is arriving, whether a line is shorted, and whether a connection is broken. Used carelessly, it gives misleading readings or causes new damage."},{"type":"heading","text":"The modes you will use most"},{"type":"list","items":["DC voltage (V⎓): measured with the board powered, probes across two points (usually a test point and ground).","Resistance (Ω): the board must be unpowered.","Continuity (beep): checks for a very low-resistance path, for example along a flex cable or track. The board must be unpowered.","Diode mode: the most-used unpowered test in board repair. It has its own lesson next.","Current (A / mA): the meter must be placed in series with the circuit. On phone boards, a bench power supply''s current display is usually more practical."]},{"type":"diagram","diagram":"multimeter","caption":"A generic meter set to DC voltage. Only voltage is measured on a powered board; the other modes need it unpowered. The black lead stays in COM; the red lead moves to the A jack only for current. Dial layouts differ between meters, so check yours."},{"type":"callout","tone":"caution","title":"Never use resistance, continuity or diode mode on a powered board","text":"In these modes the meter applies its own small voltage. On a powered board the readings are meaningless, and you can damage the meter or the board. Disconnect the battery and charger first."},{"type":"callout","tone":"caution","title":"Current mode is almost a short circuit","text":"In current mode the meter''s input has very low resistance. Placing the probes across a supply shorts it, which can blow the meter''s fuse or damage the board. Move the red lead back to the V/Ω jack after measuring current."},{"type":"heading","text":"Measuring a DC voltage"},{"type":"diagram","diagram":"measurement-setup","caption":"Same probe points, different board state. Voltage needs power; resistance, continuity and diode mode need the battery and charger disconnected. Probe orientation for diode mode is covered in the next lesson."},{"type":"example","title":"Procedure","steps":["Set the meter to DC voltage.","Place the black probe on a confirmed ground point.","Power the board in the state the test requires (off, booting, on, charging).","Touch the red probe to the test point, holding it steady so it can''t slip onto a neighbouring pad.","Compare the reading with the schematic or a known-good board of the same model, measured in the same state."],"note":"Always record the phone''s state with each reading. Many rails switch on and off depending on whether the phone is off, booting, running or charging."},{"type":"callout","tone":"tip","title":"Use fine probe tips","text":"Phone components are tiny and close together. Sharp, fine tips reduce slipping. On a powered board, a probe slipping between two pads can create a new short."}]'::jsonb),
  ('fundamentals/diode-mode', 'fundamentals', 'diode-mode', 3, 'Diode mode: finding shorts safely', 'Use diode mode on an unpowered board to find shorted lines, and compare readings the right way.', 12, 'beginner', 'published', array['Explain what a diode-mode reading represents on a phone board', 'Recognise a short to ground and an open line', 'Compare readings correctly against a known-good board']::text[], '[{"type":"text","text":"Diode mode is one of the most-used measurements in board repair because it works with the board unpowered. That makes it safe to use on a phone that might have a short, before you risk applying power."},{"type":"heading","text":"What the meter is doing"},{"type":"text","text":"In diode mode the meter pushes a small, limited test current and displays the voltage needed to push it. Across a single diode you would see its forward voltage drop. On a phone board you are measuring the combined path through everything connected to that point."},{"type":"diagram","diagram":"diode-mode","caption":"Conceptual: the meter measures the path between a test point and ground through everything connected to that line."},{"type":"heading","text":"Reading the result"},{"type":"list","items":["Very close to zero: the line is shorted, or nearly shorted, to ground.","A value that looks normal: compare it with the same point on a known-good board before deciding.","OL (over limit): no conducting path within the meter''s range. This is normal for some lines and a sign of a broken connection on others."]},{"type":"callout","tone":"key","title":"Compare, don''t guess","text":"There is no universal correct diode reading. Values depend on the board, the meter and the probe orientation. Only compare against the same point on a known-good board of the same model, using the same meter and the same probe orientation."},{"type":"heading","text":"Probe orientation"},{"type":"text","text":"Many technicians put the red probe on ground and the black probe on the test point. Others use the opposite. The two orientations give different readings. Pick one, use it every time, and write down which one you used."},{"type":"example","title":"Finding a short on a supply line","steps":["Disconnect the battery and charger, and give capacitors a moment to discharge.","Set diode mode. Put one probe on ground and the other on a capacitor on the suspect line.","A reading near zero means the line is shorted to ground.","Use the schematic or boardview to list everything connected to that line.","Locate the faulty part, for example with a thermal camera, rosin or freeze spray while carefully injecting a limited current, or by isolating parts one at a time."],"note":"Current injection must be done carefully. Keep the voltage and current limits low and suitable for that line according to its schematic. Injecting into the wrong line can damage working components."},{"type":"explorer","blockId":"pmic","text":"Supply lines, such as the main supply line and the PMIC''s output rails, are where you''ll use this test most. See how they connect in the Chipset Explorer."}]'::jsonb),
  ('fundamentals/resistors', 'fundamentals', 'resistors', 4, 'Resistors on a phone board', 'The jobs resistors do, how to read their value, how they fail and how to check one.', 10, 'beginner', 'published', array['Name the main jobs a resistor does on a phone board', 'Read a resistor''s value from a marking or a schematic', 'Explain how resistors usually fail and how to check one']::text[], '[{"type":"text","text":"You met resistance in the first lesson. A resistor is a part made to have one chosen resistance. Phone boards use a lot of them, and one failed resistor can leave a whole section without a signal or a supply, even when every chip around it is fine."},{"type":"heading","text":"The jobs resistors do"},{"type":"diagram","diagram":"resistor-jobs","caption":"Four common jobs. The symbol is the same each time; where it sits in the circuit tells you the job. Textbook symbols, not a phone circuit."},{"type":"list","items":["Limiting current: a resistor in series with a load reduces the current through it. On the PinePhone, a 100 Ω resistor (R1201) sits in the vibration motor''s supply.","Holding a level: a pull-up or pull-down keeps a line at a known voltage. These have their own lesson.","Dividing a voltage: two resistors in series give a fraction of a voltage. These have their own lesson too.","Sensing current: a low-value resistor sits in the current path, and a chip reads the small voltage across it. The PinePhone''s 2.7 Ω R1110 sits in the backlight''s return path.","Sitting in series with a fast signal: a small resistor in line with a data or clock track, such as the 33 Ω R702 on the PinePhone''s eMMC clock.","Linking: a 0 Ω resistor is a wire that can be left off. It lets one board design connect or disconnect a path."],"claims":["C-0026"]},{"type":"callout","tone":"caution","title":"An empty pad isn''t always a missing part","text":"Schematics mark some parts NC (no connect), meaning they are deliberately not fitted. On the PinePhone, 0 Ω R615 connects the eMMC pins'' supply to one rail, and R614 beside it is NC. Fitting R614 as well would join two different rails. Check the schematic before adding a part to an empty pad.","claims":["C-0026"]},{"type":"heading","text":"Reading the value"},{"type":"text","text":"Chip resistors carry a printed code when they are big enough. Many on a phone board are not: they are too small to print on, so the value has to come from the schematic or boardview."},{"type":"diagram","diagram":"resistor-marking","caption":"How printed codes work, using the rules from one manufacturer (Yageo). Other makers are similar, but some use different codes for 1% parts, so check before relying on a code."},{"type":"list","items":["Three digits: two digits, then the number of zeros. 103 is 10 followed by 3 zeros: 10,000 Ω, or 10 kΩ.","Four digits: three digits, then the number of zeros. 4702 is 470 followed by 2 zeros: 47,000 Ω, or 47 kΩ.","R marks the decimal point. 6R8 is 6.8 Ω.","A single 0 is a jumper: a 0 Ω link.","No marking at all: 0402 size and smaller, at least from this maker. An 0201 part is only 0.6 × 0.3 mm."],"claims":["C-0024"]},{"type":"callout","tone":"tip","title":"Schematic shorthand","text":"Schematics use the letter as the decimal point too. 4K7 is 4.7 kΩ, 10M is 10 MΩ, 33R is 33 Ω, 2R7 is 2.7 Ω and 0R is 0 Ω. A name like R0201 is the package size, not a value."},{"type":"heading","text":"How resistors fail"},{"type":"text","text":"Chip resistors most often fail high or open: the resistance rises, sometimes until no current flows at all. Cracks, damaged electrodes, sulfur attack and overload can all do this. Less often the resistance falls, for example when metal grows between the two ends. That needs voltage, water and contamination together, which is one more reason to look closely at liquid-damaged boards.","claims":["C-0025"]},{"type":"example","title":"Checking a resistor","steps":["Disconnect the battery and charger. Resistance is only measured on an unpowered board.","Look at it under magnification for cracks, corrosion or burning.","Get the expected value from the schematic or boardview.","Measure across its two ends on the resistance range.","Well above the expected value, or OL: suspect the resistor. Below it: don''t blame it yet. The next lesson explains why.","To be sure, compare with a known-good board, or lift one end of the part and measure again."],"note":"Replace a resistor with the same value and package size, and check the tolerance on the schematic. Small parts have small power ratings: one maker''s 0201 is rated only 1/20 W.","claims":["C-0024"]}]'::jsonb),
  ('fundamentals/series-and-parallel', 'fundamentals', 'series-and-parallel', 5, 'Series and parallel', 'The two ways parts connect, and why they explain in-circuit readings, shorted rails and dead sections.', 12, 'beginner', 'published', array['Tell series from parallel on a circuit', 'Work out a combined resistance in simple cases', 'Explain why one shorted part pulls down a whole rail', 'Explain why an in-circuit reading can only come out low']::text[], '[{"type":"text","text":"Parts can only connect in two basic ways: one after another, or side by side. These two patterns explain most of what you see at the bench, including why one capacitor can kill a rail and why a meter reading on the board often doesn''t match the printed value."},{"type":"heading","text":"Series: one path"},{"type":"text","text":"Parts in series sit one after another, so the current has only one path. The same current flows through every part, and the voltage is shared between them. Break any one part and the current stops for all of them.","claims":["C-0010"]},{"type":"heading","text":"Parallel: several paths"},{"type":"text","text":"Parts in parallel connect across the same two points. Each has the same voltage across it, and the current splits between them. Adding a path gives the current another way through, so the combined resistance goes down.","claims":["C-0010"]},{"type":"diagram","diagram":"series-parallel","caption":"Series: one path, the same current, and the voltages add up. Parallel: the same voltage, and the currents add up. Textbook symbols, not a phone circuit."},{"type":"callout","tone":"key","title":"The quick rules","text":"In series, add the resistances. In parallel, two equal resistors make half of one. For two different ones, multiply them and divide by their sum. A parallel result is always lower than the smallest resistor.","claims":["C-0010"]},{"type":"example","title":"Worked examples (textbook numbers, not a phone measurement)","steps":["Series: 10 kΩ and 4.7 kΩ give 10 + 4.7 = 14.7 kΩ.","Parallel, equal: 10 kΩ and 10 kΩ give half of one: 5 kΩ.","Parallel, different: 10 kΩ and 1 kΩ give (10 × 1) ÷ (10 + 1) = about 0.91 kΩ."],"note":"Look at the last one: the result sits close to the smaller resistor. In parallel, the lowest resistance dominates."},{"type":"heading","text":"Why a rail behaves as it does"},{"type":"text","text":"A supply rail is one big parallel connection. Every capacitor and chip on it sits between that rail and ground. That single fact explains a lot."},{"type":"diagram","diagram":"parallel-on-board","caption":"Top: every part on a rail shares the same two points, so one short pulls all of them down. Bottom: a meter can''t separate a part from whatever is in parallel with it. Textbook numbers."},{"type":"list","items":["One shorted part pulls the whole rail down, because it is in parallel with everything else. The lowest resistance dominates.","A diode-mode reading is about the same at every capacitor on that rail. Finding a low reading tells you which rail is shorted, not which part.","That''s why you locate the part with heat, or by isolating parts one at a time."]},{"type":"heading","text":"Why series parts matter"},{"type":"text","text":"Links, filter parts, connectors and tracks all sit in series with what they feed, so each one has to be intact. If one opens, everything after it loses that signal or supply."},{"type":"callout","tone":"tip","title":"Voltage on one side only","text":"If a series part has voltage on one side and none on the other, one of two things is true: the part is open, or something after it is shorted and has burnt it out or pulled the line down. With the board unpowered, check the far side for a short to ground before you fit a new part."},{"type":"heading","text":"Why in-circuit readings come out low"},{"type":"text","text":"A meter can''t see one part on its own. On the board, it measures the resistor and every other path in parallel with it. A reading taken in circuit can be lower than the printed value, and that doesn''t mean the resistor is bad. For the best result, take the part out of circuit, and always check the schematic for parallel paths first.","claims":["C-0011"]},{"type":"callout","tone":"key","title":"A parallel path can only lower a reading","text":"So a reading well above the expected value can''t be blamed on the rest of the circuit. It points at the part itself: open, cracked or badly soldered. A low reading proves nothing until you have lifted one end or compared with a known-good board. Give the reading a moment to settle, because capacitors on the line can make it drift.","claims":["C-0011"]},{"type":"example","title":"Worked reasoning (simulated readings, not a real measurement)","steps":["The schematic shows a 10 kΩ resistor on a line. Measured in circuit, unpowered, it reads OL. Parallel paths can''t raise a reading, so the resistor or its joints are bad.","Another 10 kΩ resistor reads about 2 kΩ in circuit. That could be a parallel path, so don''t replace it yet.","One end is lifted, and it now reads 10 kΩ. The resistor is fine, and the low reading came from the circuit around it."],"note":"Teaching scenario. Compare real readings with a known-good board of the same model."}]'::jsonb),
  ('fundamentals/voltage-dividers', 'fundamentals', 'voltage-dividers', 6, 'Voltage dividers', 'How two resistors make a smaller voltage, where phones use them, and what happens when one fails.', 12, 'beginner', 'published', array['Work out a divider''s middle voltage from its two resistors', 'Predict what the middle voltage does when either resistor fails', 'Recognise dividers in keys, regulators and sensors']::text[], '[{"type":"text","text":"A voltage divider is just two resistors in series, from a voltage down to ground. The same current flows through both, so the voltage shares out according to their sizes. The point between them gives a fraction of the original voltage."},{"type":"diagram","diagram":"voltage-divider","caption":"The same divider healthy and with each resistor open. Textbook numbers, with nothing connected to the middle point. A real circuit''s load will change them."},{"type":"callout","tone":"key","title":"The divider rule","text":"Middle voltage = supply × bottom ÷ (top + bottom). Only the ratio of the two resistors matters, so 10 kΩ over 10 kΩ gives the same voltage as 1 MΩ over 1 MΩ.","claims":["C-0012"]},{"type":"example","title":"Worked examples (textbook numbers, not a phone measurement)","steps":["3 V supply, 10 kΩ top, 10 kΩ bottom: 3 × 10 ÷ 20 = 1.5 V.","3 V supply, 20 kΩ top, 10 kΩ bottom: 3 × 10 ÷ 30 = 1 V.","3 V supply, 10 kΩ top, 20 kΩ bottom: 3 × 20 ÷ 30 = 2 V."],"note":"A bigger bottom resistor gives a higher middle voltage."},{"type":"heading","text":"When a part fails"},{"type":"list","items":["Top resistor open: nothing connects the middle to the supply, so it falls towards 0 V.","Bottom resistor open: no current flows, so nothing is dropped across the top resistor, and the middle rises to the supply voltage.","Supply missing: the middle reads 0 V. Check the supply before you blame either resistor."]},{"type":"callout","tone":"tip","title":"A divider is not a supply","text":"A divider can''t deliver much current. Anything connected to the middle point draws some current and pulls the voltage down. Dividers often use large values to save power, so they are easily disturbed. Trust a reading on one only after comparing with a known-good board in the same state."},{"type":"heading","text":"Real dividers on a phone"},{"type":"text","text":"Regulators: a regulator''s internal reference is lower than its output, so a divider scales the output down to a voltage it can compare with that reference. On the PinePhone, the 5 V boost converter uses a 1 MΩ resistor (R612) over a 130 kΩ resistor (R613). The formula printed on the schematic works out at about 5.2 V. That figure is calculated, not measured.","claims":["C-0013"]},{"type":"text","text":"Sensors: a thermistor changes resistance with temperature, so putting one in a divider turns temperature into a voltage. The BQ25895 charger IC uses a divider on its TS pin, and it suspends charging when that voltage goes out of range. Its limits are given as a percentage of the divider''s supply, because the ratio is what counts.","claims":["C-0015"]},{"type":"text","text":"Keys: several keys can share one wire if each gives a different voltage. The PinePhone reads both volume keys this way, through one analog input on the SoC.","claims":["C-0014"]},{"type":"diagram","diagram":"key-ladder","caption":"Each key connects a different amount of resistance to ground, so each gives a different voltage on KEYADC. Rail and resistors are from the schematic. Voltages are calculated, not measured. The keys themselves are on a flex that isn''t on the schematic."},{"type":"example","title":"Worked from the PinePhone schematic (calculated, not measured)","steps":["No key pressed: there''s no path to ground, so KEYADC sits at the ALDO3 supply, listed as 3.0 V.","VOL+ pressed: 100 kΩ on top, 6.8 kΩ below. 3.0 × 6.8 ÷ 106.8 = about 0.19 V.","VOL− pressed: 100 kΩ on top, and 6.8 + 8.2 = 15 kΩ below, because those two are in series. 3.0 × 15 ÷ 115 = about 0.39 V.","The SoC reads the voltage and works out which key was pressed."],"note":"This applies to the PinePhone v1.2b only. Other phones wire their keys differently, so read the schematic for the model on your bench.","claims":["C-0014"]},{"type":"callout","tone":"caution","title":"Residue can act like a resistor","text":"High-value nodes are sensitive to leakage, because a small leak is a big share of the current there. On a line like KEYADC, residue leaking to ground adds a new bottom resistor: 100 kΩ of leakage would put the node near 1.5 V. A low enough leak could look like a held key. Clean the area and retest before you suspect a chip.","claims":["C-0017"]},{"type":"callout","tone":"caution","title":"Small parts, big effects","text":"A feedback divider tells a regulator what voltage it is making. If the top resistor opens, the regulator sees too little voltage and can push its output too high. If the bottom one opens, the output falls towards the reference voltage. Treat these resistors with care during repair, and check them when a rail is far from its expected value.","claims":["C-0016"]}]'::jsonb),
  ('fundamentals/logic-levels', 'fundamentals', 'logic-levels', 7, 'Logic high and logic low', 'What high and low really mean, why they depend on the supply, and how to read digital lines at the bench.', 10, 'beginner', 'published', array['Explain logic high, logic low and the undefined zone between them', 'Judge a line against its own supply, not a fixed number', 'Explain why a steady in-between voltage deserves attention']::text[], '[{"type":"text","text":"Digital chips work in two states: high and low. Reset lines, enable lines and interrupts are all simply high or low at any moment. High means close to that line''s supply. Low means close to ground. Reading these states correctly is one of the fastest ways to see what a board is doing."},{"type":"heading","text":"Two bands with a gap"},{"type":"text","text":"A chip''s input doesn''t need an exact voltage. Anything above one threshold counts as high, and anything below a lower threshold counts as low. Between the two is a gap where the datasheet promises nothing."},{"type":"diagram","diagram":"logic-levels","caption":"Input limits for one example logic gate (TI SN74LVC1G04), drawn to scale. They are a different size at each supply, and other chips have their own limits."},{"type":"list","items":["At a 1.8 V supply, that example gate reads high from 0.65 × supply (1.17 V) and low up to 0.35 × supply (0.63 V).","At 3.3 V, the same gate reads high from 2 V and low up to 0.8 V.","I²C uses 70% and 30% of its supply as the limits.","The AXP803 PMIC''s power key pin reads high from 1.3 V and low up to 0.5 V."],"claims":["C-0018"]},{"type":"callout","tone":"caution","title":"High is relative","text":"1.8 V on a 1.8 V line is a healthy high. The same 1.8 V on a 3.3 V line is not, because it''s below the 2 V that example gate needs. Before you judge a reading, find that line''s supply on the schematic.","claims":["C-0018"]},{"type":"heading","text":"High doesn''t always mean on"},{"type":"text","text":"Some signals are active-low: they do their job when low. You met this with reset lines. Names often show it with a bar, _N, _B or #. On the PinePhone, the SoC''s reset line is AP-RESET#, and it comes from the PMIC''s PWROK power-good output. Low means held in reset, and high means running. The PMIC pulls it low when it shuts down.","claims":["C-0020"]},{"type":"heading","text":"Why the gap matters"},{"type":"text","text":"A CMOS input has two transistors, one to the supply and one to ground. Normally one is off. At an in-between voltage both conduct at once, so current flows straight through. TI reports several milliamps per input on its 5 V logic, and outputs can oscillate. The risk is the same reason a line must never be left floating, which the next lesson deals with.","claims":["C-0019"]},{"type":"heading","text":"Reading logic with a multimeter"},{"type":"list","items":["A steady line reads its true level. Note the phone''s state, because a line can legitimately change between off, booting and running.","A busy line reads an average. A clock or active data line can show an in-between voltage, and that''s normal. It says nothing about whether the signal is good.","A line that should be steady but sits in the gap is worth chasing. Likely causes are a missing pull resistor, a chip with no supply, leakage, or two outputs fighting.","To see a signal actually switching, you need an oscilloscope or logic analyser."]},{"type":"example","title":"Worked reasoning (simulated readings, not a real measurement)","steps":["The schematic shows an active-low reset line on a 1.8 V supply. It should be high once the phone is running.","It reads close to 0 V. The chip is being held in reset, so find what''s holding it: its driver, or a short to ground.","On another phone, the same line reads about half the supply and stays there. That''s neither high nor low.","Check the line''s pull resistor, the driver''s supply and any residue around the line, then compare with a known-good board in the same state."],"note":"Teaching scenario. Readings are described in words because real values depend on the board."}]'::jsonb),
  ('fundamentals/pull-up-and-pull-down', 'fundamentals', 'pull-up-and-pull-down', 8, 'Pull-up and pull-down resistors', 'How one resistor gives a line a known level, why keys and buses depend on it, and how to find the fault when it fails.', 14, 'beginner', 'published', array['Explain what pull-up and pull-down resistors do', 'Explain how keys and open-drain lines depend on them', 'Work out why a line is stuck low, stuck high or floating']::text[], '[{"type":"text","text":"If nothing is driving a line, it floats. Its voltage drifts wherever leakage and noise take it, and that can land it in the gap between high and low. A pull resistor fixes that. A pull-up connects the line to a supply and holds it high. A pull-down connects it to ground and holds it low. The hold is gentle, so anything actively driving the line can easily overpower it.","claims":["C-0019","C-0021"]},{"type":"diagram","diagram":"pull-resistors","caption":"Left: a pull-up holds the line high until a key pulls it to ground. Right: a pull-down holds it low until a key connects it to the supply. Textbook symbols, not a phone circuit."},{"type":"heading","text":"Why a resistor and not a wire?"},{"type":"text","text":"If the line were wired straight to the supply, pressing a key would short the supply to ground. The resistor limits that current. With 3.3 V across 10 kΩ, only 0.33 mA flows while the key is held. Those numbers are textbook ones, and the sum is just Ohm''s law."},{"type":"heading","text":"Keys"},{"type":"text","text":"Pressing a key usually means pulling a line low. On the AXP803 PMIC, the PWRON pin is pulled up inside the chip by about 100 kΩ to its 1.8 V internal supply, and the key goes between PWRON and ground. The line sits high, and a press pulls it low. The PMIC only accepts a press that stays low for at least 32 ms, which filters out brief glitches. On the PinePhone, this line also has a 1 kΩ series resistor, R602.","claims":["C-0022"]},{"type":"callout","tone":"key","title":"Pull-ups can be inside the chip","text":"No pull-up on the schematic doesn''t mean there isn''t one. Many chips have them built in, so there is no resistor to find on the board. Check the chip''s datasheet if you can get it, or compare the idle level with a known-good board.","claims":["C-0022"]},{"type":"heading","text":"Open-drain lines and I²C"},{"type":"text","text":"An open-drain output has one transistor, to ground. It can pull a line low, but it can''t push it high. To go high it simply lets go, and the pull-up does the lifting. I²C works this way: both of its lines connect to a supply through pull-ups, and they sit high when the bus is free. Every device shares the same lines, so any one of them can pull a line low.","claims":["C-0021"]},{"type":"diagram","diagram":"open-drain-bus","caption":"Only the resistor lifts the line. Any device can pull it down, so one faulty device can hold the whole line low for all of them. Generic parts, not a phone circuit."},{"type":"list","items":["On the PinePhone, 2 kΩ resistors R1101 and R1102 lift the touch controller''s I²C lines to GPIO0-LDO. That same rail feeds the touch connector, so if it''s missing, the pull-ups and the touch supply are gone together.","The AXP803''s interrupt output is open drain and needs a 10 kΩ pull-up. On the PinePhone, that''s R605, going to VCC-RTC.","The PinePhone''s eMMC has one of each: R704 (10 kΩ) lifts EMMC-CMD to VCC-PC, and R703 (10 kΩ) pulls EMMC_DS down to ground."],"claims":["C-0022"]},{"type":"heading","text":"Why the value matters"},{"type":"text","text":"A line and everything on it has capacitance, and a pull-up has to charge that capacitance each time the line rises. Too large a resistor makes the line rise slowly and disturbs it easily. Too small a resistor wastes current every time the line is held low. TI usually recommends 1 to 10 kΩ on a logic bus, the I²C specification ties the upper limit to bus capacitance and rise time, and phones also use larger values where a line rarely changes. Replace a pull resistor with the value on the schematic.","claims":["C-0021"]},{"type":"heading","text":"USB-C: a pull-up meets a pull-down"},{"type":"text","text":"A USB-C charger puts a pull-up on the CC pins, and a phone that wants power puts a pull-down on them, typically 5.1 kΩ. The two are in series, so they form a divider. The charger sees that pull-down as proof a device is attached and then supplies power, and the pull-up''s value advertises how much current is on offer. So a damaged CC line can stop a USB-C to USB-C charger from ever turning on, even though the rest of the charging path is fine.","claims":["C-0023"]},{"type":"heading","text":"Finding the fault"},{"type":"list","items":["Stuck low: the pull-up''s rail may be missing, or something is shorted or holding the line down. Check the rail first, because it''s the quickest check.","In the gap: suspect a pull resistor that is open or unpowered, or leakage.","Stuck high when it should go low: the part that pulls it low isn''t doing so. That may be a chip with no supply, a broken track or an open key flex."]},{"type":"example","title":"A peripheral isn''t detected: checking its I²C lines","steps":["With the phone in the state where the peripheral should work, measure both lines at idle. They should sit close to the pull-up''s rail.","If they read low, measure that rail first. No rail means no pull-up.","If the rail is fine, remove power and measure each line to ground. Compare with a known-good board of the same model.","Disconnect peripherals on that bus one at a time, where you can. If a line recovers, the last part you unplugged was holding it down.","Still low with everything removed: inspect the line for residue or a short, then measure the pull resistor between the line and its rail."],"note":"Only measure resistance with the board unpowered. Measuring a pull resistor in circuit reads everything in parallel with it, so a low reading isn''t proof of a fault."}]'::jsonb),
  ('fundamentals/capacitors', 'fundamentals', 'capacitors', 9, 'Capacitors and why they short', 'What capacitors do on a phone board and how they fail.', 10, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/inductors-and-coils', 'fundamentals', 'inductors-and-coils', 10, 'Inductors and coils', 'Where inductors appear in power circuits and how to check them.', 8, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/diodes-and-protection', 'fundamentals', 'diodes-and-protection', 11, 'Diodes and protection parts', 'Diodes, TVS and ESD protection: what they guard against.', 10, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/transistors-and-mosfets', 'fundamentals', 'transistors-and-mosfets', 12, 'Transistors and MOSFETs as switches', 'How switching components turn loads on and off.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/reading-schematics-and-boardviews', 'fundamentals', 'reading-schematics-and-boardviews', 13, 'Reading schematics and boardviews', 'Finding a line, its components and its test points.', 14, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/power-path', 'power', 'power-path', 1, 'From battery to rails: the power path', 'Follow power from the USB port and battery through the PMIC to the rails that feed every part of the phone.', 12, 'beginner', 'published', array['Trace the conceptual power path from USB input to the loads', 'Explain the difference between the main supply line and PMIC rails', 'Explain why a short on the main supply line makes a phone appear dead']::text[], '[{"type":"text","text":"A phone doesn''t run everything directly from the battery. Power passes through several stages, and each one changes or protects it. Knowing the stages tells you where to measure first."},{"type":"diagram","diagram":"power-path","caption":"Conceptual power path. Real designs differ in the number of PMICs, which loads use the main supply line directly, and how the charging IC connects."},{"type":"heading","text":"Stage by stage"},{"type":"list","ordered":true,"items":["USB input: the charging port, filtering, and protection such as over-voltage protection on many designs.","Charging IC: charges the battery and, on many designs, also supplies the system.","Battery and battery connector.","Main system supply line: feeds the PMIC(s) and, on many designs, some high-power loads directly. Its name varies by platform, so read it from the schematic.","PMIC(s): buck converters and LDO regulators turn the main supply into many lower-voltage rails.","Rails to loads: the SoC, memory, display, cameras and other parts."]},{"type":"heading","text":"Buck converters and LDOs"},{"type":"text","text":"A buck converter switches on and off very quickly and uses an inductor to step voltage down efficiently. That is why you see inductors (coils) around a PMIC. An LDO (low-dropout regulator) steps voltage down without switching. It is simpler and quieter but less efficient, so it is often used for sensitive or low-current rails."},{"type":"callout","tone":"key","title":"Why a short on the main supply line matters","text":"Everything downstream is fed from the main supply line. A short there usually makes the phone appear dead, and a bench power supply may show current as soon as it is connected, before you press power."},{"type":"callout","tone":"caution","title":"No universal rail values","text":"Rail names, voltages and which rails exist all vary by model and board revision. Take expected values from that model''s schematic or a known-good board, never from another phone."},{"type":"explorer","blockId":"charging","text":"See how Battery & Charging and the PMIC connect in the Chipset Explorer."}]'::jsonb),
  ('power/dc-power-supply-current-draw', 'power', 'dc-power-supply-current-draw', 2, 'Reading current draw on a DC power supply', 'Use a bench power supply safely and learn the general current patterns that point toward a fault area.', 14, 'intermediate', 'published', array['Connect a bench power supply safely', 'Recognise common current-draw patterns', 'Link each pattern to the boot stage and fault areas to check next']::text[], '[{"type":"text","text":"A bench DC power supply can stand in for the battery and show how much current the phone draws, moment by moment. Watching that number while you press power is one of the fastest ways to narrow down a dead phone."},{"type":"callout","tone":"caution","title":"Set up safely","text":"Use a voltage within the rated range of that model''s battery (check the battery label or service information). Start with a low current limit and raise it only when needed. Check polarity before connecting, because reversed polarity can destroy components. Use a proper adapter that fits the battery connector."},{"type":"heading","text":"Common patterns"},{"type":"text","text":"These are general starting points, not diagnoses. Normal current behaviour differs between models, so always compare with a known-good phone of the same model."},{"type":"list","items":["Current flows as soon as you connect, before pressing power, and may hit the limit: suggests a short on the main supply line or something connected to it.","No current at all when pressing power: the power-on trigger may not be reaching the PMIC, or the PMIC is not starting. Check the power key line, the battery connector and the supply path.","A small jump that falls straight back to zero: the power-on sequence starts but stops. Possible causes include a missing rail, a clock or reset problem, or a fault on a rail that causes the sequence to abort.","Current rises and then stays fixed without changing: boot may be stuck early, for example the SoC is not loading from storage.","Current rises and varies as if booting, then drops and the cycle repeats: a boot loop. Firmware, storage, RAM and power problems can all cause this."]},{"type":"diagram","diagram":"current-patterns","caption":"The five patterns as shapes over time. The dashed line marks the power key press. There are no values because normal current differs between models: compare with a known-good phone of the same model."},{"type":"example","title":"Worked reasoning (simulated scenario, not a real measurement)","steps":["Simulated scenario: a phone appears dead after liquid exposure.","On the bench supply, current flows immediately on connection, before pressing power, and reaches the limit you set.","This pattern points to a short on the main supply line or something connected to it.","Next step: disconnect power, check that line in diode mode, then locate the shorted part."],"note":"This is a teaching scenario. Real readings depend on the model and must be compared with a known-good board."},{"type":"explorer","blockId":"pmic","text":"Each pattern maps to a stage of power-up. Review the PMIC and Clocks & Reset blocks in the Chipset Explorer."}]'::jsonb),
  ('power/ldo-regulators', 'power', 'ldo-regulators', 3, 'LDO regulators', 'How an LDO holds a steady rail, what dropout and heat mean, and how to diagnose a missing or low LDO rail.', 14, 'intermediate', 'published', array['Explain how an LDO holds its output steady', 'Explain dropout, and why LDOs get warm', 'Follow a bench order for a missing or low LDO rail']::text[], '[{"type":"text","text":"An LDO (low-dropout regulator) makes a steady lower voltage from a higher one. Think of it as a resistor in series with the rail that keeps adjusting itself. It drops whatever extra voltage there is and turns it into heat, moment by moment, so the output stays put while the input and the load change."},{"type":"heading","text":"What''s inside"},{"type":"diagram","diagram":"ldo-block","caption":"The feedback loop inside an LDO. The divider and error amplifier keep the pass transistor adjusted. Generic block diagram: inside a PMIC you can''t reach these parts."},{"type":"list","ordered":true,"items":["Pass transistor: sits in series between input and output, and carries all the load current.","Reference: a steady internal voltage to compare against.","Sampling resistors: a voltage divider that feeds back a fraction of the output.","Error amplifier: compares that fraction with the reference and adjusts the pass transistor. If the output sags, it turns the transistor on harder."],"claims":["C-0027"]},{"type":"callout","tone":"tip","title":"PMIC LDOs are set digitally","text":"The LDOs inside a PMIC usually have no resistors to find on the board. On the AXP803, each LDO''s voltage is set in small steps through registers, over a serial link from the SoC. Software can change or switch off a rail, so the same LDO can read differently in different states.","claims":["C-0033"]},{"type":"heading","text":"LDOs and buck converters"},{"type":"text","text":"The PinePhone''s power tree shows how the two are shared out. Its DC/DC converters are rated 1.5 to 3 A and feed the heavy loads: the CPU, memory and main system. Its LDOs are rated about 100 to 500 mA and feed lighter loads such as cameras, analog circuits, sensors and touch.","claims":["C-0033"]},{"type":"heading","text":"Dropout"},{"type":"text","text":"An LDO can only drop voltage, never add it. The input has to stay above the output by a small margin, called the dropout voltage. Below that the LDO can''t regulate. Its pass transistor is fully on and acts like a small resistor, so the output simply follows the input down.","claims":["C-0028"]},{"type":"diagram","diagram":"ldo-dropout","caption":"Output against input for a generic LDO. Regulating: the output holds steady. Dropout: it follows the input down. Off: the input is too low to run at all. No values, because they differ for every part."},{"type":"callout","tone":"key","title":"Low input, low output","text":"If an LDO''s output is low, measure its input before anything else. TI''s example is a 3.3 V LDO that needs about 3.65 V at its input when supplying 1 A. Any LDO rail set close to the supply will sag first when the battery runs low, or if a bench supply is set too low.","claims":["C-0028"]},{"type":"heading","text":"Why LDOs get warm"},{"type":"text","text":"Almost the same current flows in as out, so the extra voltage has to go somewhere. It becomes heat in the pass transistor. The loss is the voltage dropped multiplied by the current, and the bigger the drop, the less efficient the LDO.","claims":["C-0029"]},{"type":"example","title":"Worked example (textbook numbers, not a phone measurement)","steps":["Input 3.8 V, output 1.8 V, load 100 mA.","Voltage dropped: 3.8 − 1.8 = 2 V.","Heat: 2 V × 0.1 A = 0.2 W.","Efficiency: about 1.8 ÷ 3.8 = 47%. More than half the power becomes heat."],"note":"So a warm LDO under load isn''t automatically a fault. That is the part to compare with a known-good phone doing the same job. On a PMIC, this heat comes out of the PMIC itself."},{"type":"heading","text":"How LDOs protect themselves"},{"type":"text","text":"Many LDOs have a current limit. Past it, the output voltage falls instead of the part being destroyed. TI''s TLV700 then gets hot and can cycle between current limit and thermal shutdown for as long as the fault remains. That is why a short on an LDO rail often reads as a low or missing rail, not always a dead LDO. On the AXP803, all outputs have current limiting, but only the DC/DC outputs are described as triggering a forced shutdown when they sag, so a shorted LDO rail may leave a phone running with one section missing.","claims":["C-0030"]},{"type":"callout","tone":"caution","title":"Output capacitors are part of the circuit","text":"An LDO''s feedback loop depends on its output capacitor. TI''s TLV700 needs 1 µF for stability, and the PinePhone fits 4.7 µF on each LDO output. A missing or wrong capacitor can leave a rail unstable, so replace them with the value on the schematic.","claims":["C-0031"]},{"type":"callout","tone":"caution","title":"Take care when injecting voltage","text":"A PMOS LDO such as TI''s TLV700 has a body diode that conducts from output to input when the output is higher, and TI warns that this current isn''t limited. Injecting voltage into an LDO''s output to find a short can push current back into whatever feeds it. Keep voltage and current limits low, and use the rail''s own voltage from the schematic.","claims":["C-0032"]},{"type":"heading","text":"Diagnosing a missing or low rail"},{"type":"text","text":"TI''s TLV700 datasheet says it regulates when its input is high enough and the load is below the current limit, and it also has to be enabled. The fault-finding order follows those conditions, and it starts with whether the rail should be on at all.","claims":["C-0028","C-0030"]},{"type":"diagram","diagram":"ldo-fault-flow","caption":"The order to check a rail. Each step rules something out, and the LDO itself is suspected last."},{"type":"list","ordered":true,"items":["Should it be on? Most AXP803 LDOs default to off and wait for software, so a missing rail on a phone that won''t boot may be normal. Compare with a known-good board in the same state.","Input: measure it. No input means work backwards along the supply. A low input explains a low output.","Enable: on a separate LDO, check its enable pin against the schematic. A PMIC LDO is enabled by software, so you can''t measure that directly.","Short: with power off, use diode mode on the rail''s capacitor. If it''s shorted, find the shorted part. That is usually a better bet than replacing the LDO.","Load: disconnect the module or flex on that rail, where you can, and retest. If the rail returns, the load was the fault.","LDO: only when input, enable and load are all cleared. For a PMIC LDO, that means the whole PMIC, so be sure first."],"claims":["C-0033"]},{"type":"example","title":"Worked reasoning (simulated scenario, not a real measurement)","steps":["Simulated scenario: the phone boots, but it reports no camera.","The schematic shows the camera''s supply comes from an LDO. With the camera app open, that rail reads near zero. A known-good phone in the same state shows its normal voltage.","The LDO''s input is present.","With power off, diode mode on the rail''s capacitor reads close to zero: the rail is shorted.","Unplugging the camera module clears the short, so the module is the fault and the LDO is fine."],"note":"Teaching scenario. Readings are described in words because real values depend on the board."},{"type":"explorer","blockId":"pmic","text":"See the PMIC in the Chipset Explorer, and what each rail feeds."}]'::jsonb),
  ('power/buck-converters', 'power', 'buck-converters', 4, 'Buck converters', 'How switching regulators make the high-current rails, and what failure looks like.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/charging-circuits', 'power', 'charging-circuits', 5, 'Charging circuits', 'The USB input path, protection and the charging IC.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/finding-shorts-on-rails', 'power', 'finding-shorts-on-rails', 6, 'Finding shorts on rails', 'Locating a shorted component safely and efficiently.', 14, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/power-key-and-power-on', 'power', 'power-key-and-power-on', 7, 'The power key and power-on trigger', 'How a key press reaches the PMIC.', 8, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/battery-connector-and-protection', 'power', 'battery-connector-and-protection', 8, 'Battery connector and protection', 'Battery lines, temperature/ID and protection circuits.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('boot/what-happens-when-you-press-power', 'boot', 'what-happens-when-you-press-power', 1, 'What happens when you press power', 'The stages a phone goes through from the power key to the operating system, and how to use them to narrow down a fault.', 12, 'beginner', 'published', array['List the main boot stages in order', 'Link each stage to the blocks involved', 'Use the stage where boot stops to narrow down a fault']::text[], '[{"type":"text","text":"Booting is a relay race. Each stage must finish before the next can start. If you can tell which stage the phone reaches, you have already ruled out a large part of the board."},{"type":"diagram","diagram":"boot-sequence","caption":"Conceptual boot sequence. The exact order, and which chip handles each step, varies by platform."},{"type":"heading","text":"Stage by stage"},{"type":"list","ordered":true,"items":["Power key: pressing it signals the power-management circuit. On many designs the key line goes to the PMIC; check the schematic.","Power-on sequence: supply rails are switched on in a defined order.","Clocks start: reference clocks begin running.","Reset released: once rails and clocks are ready, the SoC is released from reset.","Boot ROM: code built permanently into the SoC runs first and looks for the first bootloader in storage. If it can''t load one, many SoCs offer an emergency USB download mode.","Bootloaders: load from storage, initialise RAM, and check the software that follows. On most phones this chain is protected by digital signatures.","Operating system: the kernel and OS start, and drivers bring up the display, touch, cameras, radios and the rest."]},{"type":"callout","tone":"key","title":"Use the stage to narrow the fault","text":"If boot stops very early (no rails, no clock), suspect power and timing. If the boot ROM runs but no bootloader loads, suspect storage, its supply, or firmware. If the logo appears but the OS never finishes starting, firmware, storage and RAM are common suspects. Peripheral faults usually show only once the OS is running."},{"type":"heading","text":"Signs you can observe"},{"type":"list","items":["The current pattern on a bench power supply (see the power systems course).","Whether a computer detects the phone, and in which mode.","Whether the logo appears, and how far the boot animation gets.","A vibration at power-on, on phones that do this."]},{"type":"explorer","blockId":"soc","text":"See how the SoC depends on the PMIC, clocks, RAM and storage in the Chipset Explorer."}]'::jsonb),
  ('boot/boot-rom-and-download-modes', 'boot', 'boot-rom-and-download-modes', 2, 'Boot ROM and download modes', 'What emergency USB modes tell you about the board.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('boot/bootloaders-and-secure-boot', 'boot', 'bootloaders-and-secure-boot', 3, 'Bootloaders and secure boot', 'The signed chain from boot ROM to OS.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('boot/reading-boot-logs', 'boot', 'reading-boot-logs', 4, 'Reading boot and flashing logs', 'Using tool output to find where boot stops.', 12, 'advanced', 'planned', '{}'::text[], '[]'::jsonb),
  ('boot/boot-loop-diagnosis', 'boot', 'boot-loop-diagnosis', 5, 'Diagnosing boot loops', 'Separating firmware, power, storage and RAM causes.', 14, 'advanced', 'planned', '{}'::text[], '[]'::jsonb),
  ('boot/firmware-vs-hardware', 'boot', 'firmware-vs-hardware', 6, 'Firmware fault or hardware fault?', 'Tests that separate software problems from board faults.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('clocks/crystals-and-oscillators', 'clocks', 'crystals-and-oscillators', 1, 'Crystals and oscillators', 'What a clock signal is, how crystals and oscillators produce one, and why a board without its clock can''t start.', 10, 'intermediate', 'published', array['Explain what a clock signal does for digital chips', 'Tell a passive crystal from an active oscillator', 'Name the main clock sources on a typical phone board']::text[], '[{"type":"text","text":"Digital chips do their work in steps, and a clock signal sets the pace of those steps. It is a voltage that switches or swings up and down at a steady rate. Without a clock, a processor has a supply and is out of reset, but it never takes its first step."},{"type":"heading","text":"Crystals"},{"type":"text","text":"A crystal is a small piece of quartz cut so that it vibrates at one very precise frequency. Quartz is piezoelectric: squeezing it makes a voltage, and a voltage makes it flex. That lets an electronic circuit keep it vibrating and read the vibration back as a timing signal."},{"type":"list","items":["A crystal is passive. It cannot run on its own. An oscillator circuit, usually inside the chip it serves (such as the PMIC or SoC), drives it.","It normally sits close to that chip, with two signal connections and often a small capacitor on each side. These load capacitors help set the exact frequency.","On the board it usually looks like a small metal-lidded or ceramic rectangle, often marked with its frequency or a manufacturer code."],"claims":["C-0004"]},{"type":"heading","text":"Oscillators"},{"type":"text","text":"An oscillator module contains the crystal and its drive circuit in one package. It needs a power supply and gives out a finished clock signal on an output pin. Radio sections often use temperature-compensated oscillators (TCXOs), because radio frequencies must stay accurate as the phone warms up and cools down."},{"type":"diagram","diagram":"crystal-oscillator","caption":"Left: a crystal can''t run by itself; the oscillator circuit is inside the chip it serves, with a load capacitor on each side. Right: an oscillator module has its own supply and outputs a finished clock. Generic symbols; pin names and values come from the schematic."},{"type":"callout","tone":"key","title":"Crystal or oscillator: why it matters","text":"A crystal depends on the chip that drives it, so a missing clock can be caused by that chip or its supply, not only by the crystal. An oscillator depends on its own supply. Check its supply line and enable signal (if it has one) against the schematic before blaming the part."},{"type":"heading","text":"Clocks on a typical phone"},{"type":"list","items":["Sleep / RTC clock: a low-frequency clock, typically 32.768 kHz, used for timekeeping and low-power functions. It has its own lesson later in this course.","Main reference clock: the base timing for the SoC. Faster internal clocks are made from it. The frequency depends on the platform.","Radio and Wi-Fi clocks: these sections may share the main reference or have their own sources."],"claims":["C-0002"]},{"type":"callout","tone":"caution","title":"Frequencies come from the schematic","text":"Only the sleep clock''s 32.768 kHz is close to universal. Main and radio clock frequencies differ between platforms and models. Read them from the schematic or the part marking. Never assume them from another phone."},{"type":"explorer","blockId":"clock","text":"See where clocks and reset sit in the Chipset Explorer, and what depends on them."}]'::jsonb),
  ('clocks/crystals-on-the-board', 'clocks', 'crystals-on-the-board', 2, 'Crystals on the board', 'Read a crystal circuit on a real schematic, learn what each test can prove, and choose the right replacement.', 12, 'intermediate', 'published', array['Identify a crystal and the parts around it on a schematic', 'Choose bench tests that prove something, and avoid those that don''t', 'Choose a correct replacement crystal']::text[], '[{"type":"text","text":"The last lesson explained what a crystal does. This one is about working on one: what the circuit around it looks like on a real phone, what you can actually prove with your tools, and how to replace one properly."},{"type":"heading","text":"A real example"},{"type":"diagram","diagram":"crystal-circuit","caption":"Both crystals as drawn on the PinePhone v1.2b schematic. Values and part numbers apply to that phone only: read them from the schematic of the model on your bench."},{"type":"text","text":"The PinePhone''s 32.768 kHz crystal (X500) sits on the SoC, not the PMIC, so don''t assume where a sleep crystal lives. Its main 24 MHz crystal (X501) is a 4-pad part: two pads carry the signal and two are ground. Not every 4-pad crystal has its pads in the same places, so read the footprint from the schematic.","claims":["C-0035"]},{"type":"heading","text":"What each part does"},{"type":"list","items":["Amplifier: an inverter inside the chip keeps the crystal vibrating. A crystal never runs by itself.","Feedback resistor: sits across the crystal and biases that amplifier so it can work, usually 1 to 10 MΩ. The PinePhone''s 32.768 kHz circuit has one on the board (R500, 10 MΩ). Its 24 MHz circuit shows none, so it''s presumably inside the chip.","Load capacitors: one from each side to ground. The crystal sees them in series plus some stray capacitance, so two 18 pF capacitors count as about 9 pF plus stray.","Series resistor: can limit how hard the crystal is driven. The PinePhone''s R502 is 0 Ω, so here it''s a plain link."],"claims":["C-0034","C-0035"]},{"type":"heading","text":"What your tools can prove"},{"type":"list","items":["Microscope: cracks, residue, corrosion and damaged load capacitors. Do this first. It costs nothing and risks nothing.","Meter, crystal out of circuit: a crystal doesn''t conduct DC, so a healthy one reads open. A low reading means it''s faulty. An open reading only shows it isn''t shorted, not that it vibrates.","Meter, crystal in circuit: you are also reading what''s in parallel with it. On the PinePhone''s 32.768 kHz crystal, that includes the 10 MΩ resistor. A reading near that value is normal and says nothing about the crystal.","Diode mode to ground on each crystal pin: compare with a known-good board. A shorted load capacitor pulls that pin to ground, which stops the oscillator.","DC voltage on the crystal pins: this may show the amplifier is biased. It can''t prove oscillation.","Oscilloscope: the only one here that shows the clock running, if you probe it correctly."],"claims":["C-0036","C-0034"]},{"type":"callout","tone":"caution","title":"A standard scope probe can stop a crystal","text":"A passive probe adds about 10 to 15 pF, close to the size of the load capacitors themselves, and that can shift or stop the oscillation. Check the clock at a buffered output or at another chip that receives it, where the schematic has one. On the crystal pins, use a low-capacitance active probe. With only a passive probe, a flat line on a crystal pin proves nothing. A clean waveform shows it''s running, but don''t trust the exact frequency.","claims":["C-0003"]},{"type":"heading","text":"Marginal crystals"},{"type":"text","text":"A crystal doesn''t always fail outright. If its losses are too high, it may fail to start or may stop over a temperature range, so a phone can work when warm and fail when cold, or the other way round. Oversized load capacitors can cause start-up problems in the same way. Small frequency errors matter on radio clocks too, because the error is multiplied along with the frequency.","claims":["C-0037"]},{"type":"heading","text":"Replacing a crystal"},{"type":"list","ordered":true,"items":["Read the frequency, package, load capacitance and tolerance from the schematic or parts list. The frequency is often printed on the part, but the rest isn''t.","Match the load capacitance, not just the frequency. One 3.2 × 1.5 mm crystal range comes at 32.768 kHz with load capacitance of 12.5, 9, 7, 6 or 4 pF, and a wrong one shifts the frequency.","Keep the original load capacitors unless the schematic says otherwise.","Follow that part''s soldering limits. Crystal datasheets set a maximum. Abracon''s ABS07, for example, allows a 260 °C peak, up to 30 s near that peak, and two reflow cycles.","Confirm the fix with the function that was failing, such as timekeeping after power loss, or the radio working. Don''t stop at a change in the current pattern."],"claims":["C-0004","C-0005"]},{"type":"callout","tone":"tip","title":"Crystal or chip?","text":"A dead clock doesn''t prove a dead crystal. Before you replace one, check the driving chip''s supply and rule out a shorted load capacitor. Then a new crystal, fitted correctly, is a fair test of the crystal itself, because the amplifier and capacitors have already been cleared."},{"type":"explorer","blockId":"clock","text":"See what depends on the clocks in the Chipset Explorer."}]'::jsonb),
  ('clocks/rtc-and-sleep-clock', 'clocks', 'rtc-and-sleep-clock', 3, 'The RTC and sleep clock', 'What the real-time clock and its low-frequency sleep clock do, and why a fault there can affect power-on as well as the time.', 8, 'intermediate', 'published', array['Explain what the RTC and sleep clock are for', 'Explain why 32.768 kHz is the usual sleep-clock frequency', 'Recognise symptoms that point towards the sleep clock']::text[], '[{"type":"text","text":"The real-time clock (RTC) keeps track of time, even while the phone is switched off. It runs from a slow, low-power clock usually called the sleep clock. On many designs, the RTC and its sleep clock are part of the PMIC."},{"type":"heading","text":"Why 32.768 kHz?"},{"type":"diagram","diagram":"rtc-divider","caption":"Halve 32,768 Hz fifteen times and you get exactly 1 Hz: one tick per second. This is arithmetic; how a particular RTC divides its clock is in that chip''s datasheet."},{"type":"text","text":"32,768 is 2 to the power of 15. A simple counter that halves the signal 15 times gets exactly one tick per second. That makes timekeeping simple and lets the circuit run on very little power. Crystals at this frequency are small, cheap and accurate enough for a clock.","claims":["C-0001"]},{"type":"heading","text":"More than just the time"},{"type":"list","items":["Low-power timing: while the phone sleeps, the fast clocks are stopped to save power. The slow clock keeps timers and wake-up alarms running.","Power-on: on some designs the PMIC needs the sleep clock running before it completes its power-on sequence. A missing sleep clock can then look like a dead phone.","Alarms: the RTC can wake the phone at a set time, which is how some phones power on for an alarm."],"claims":["C-0006"]},{"type":"callout","tone":"tip","title":"Not every design has a separate crystal","text":"Some platforms make the sleep clock without a dedicated 32.768 kHz crystal, for example by deriving it from another clock. Check the schematic before looking for a crystal that may not be there.","claims":["C-0006"]},{"type":"heading","text":"Symptoms that point here"},{"type":"list","items":["The date and time reset to a default after the battery is removed or goes flat.","The phone won''t start, with a current draw that starts and stops early in the power-on sequence. Many other faults look like this too.","Alarms or scheduled wake-ups don''t fire while the phone is off or asleep."]},{"type":"callout","tone":"caution","title":"A wrong time isn''t always hardware","text":"Phones usually set their time from the network or the internet once they''re running. A wrong time after boot can be a settings or software issue. It points to the RTC mainly when the time resets every time power is lost."},{"type":"explorer","blockId":"pmic","text":"See the PMIC in the Chipset Explorer. On many designs it hosts the RTC and sleep clock."}]'::jsonb),
  ('clocks/reset-signals', 'clocks', 'reset-signals', 4, 'Reset signals', 'Power-on reset, watchdog resets and peripheral reset lines: what holds chips in a known state, and what lets them go.', 10, 'intermediate', 'published', array['Explain why chips are held in reset at power-on', 'Explain how a watchdog causes a restart', 'Describe how peripheral reset lines are used']::text[], '[{"type":"text","text":"While supply rails are still rising, a chip''s internal state is unpredictable. A reset signal holds the chip in a known starting state until its supplies and clocks are ready, then lets it go. Releasing reset is what lets the chip begin working."},{"type":"heading","text":"Power-on reset"},{"type":"list","items":["During the power-on sequence, reset is held active while the rails come up.","Once the right supplies are stable (and, on many designs, the clocks are running), the reset is released and the SoC starts its boot ROM.","On many designs the PMIC controls the SoC''s main reset as part of its sequence. Check the schematic for your board."]},{"type":"diagram","diagram":"reset-timing","caption":"The order at power-on: supplies rise and settle, the clock starts, and only then is the active-low reset released so the SoC can start. The order and timing vary by platform; no times or levels are shown."},{"type":"callout","tone":"key","title":"Active-low is common","text":"Many reset lines are active-low: the chip is held in reset while the line is low, and released when it goes high. Schematics often mark these with a bar over the name or a suffix such as _N or _B. Check the schematic before deciding whether a level is right or wrong."},{"type":"heading","text":"Watchdog resets"},{"type":"text","text":"A watchdog is a timer that software must keep restarting, often called \"kicking\" or \"feeding\" it. If software hangs and stops doing that, the timer runs out and the watchdog restarts the system. It is a safety net: a stuck phone recovers by itself instead of freezing forever."},{"type":"diagram","diagram":"watchdog","caption":"Top: healthy software keeps restarting the timer, so nothing happens. Bottom: a hang lets the timer run out and the phone restarts. If the same hang happens on every start, you get a boot loop."},{"type":"callout","tone":"tip","title":"Watchdogs and boot loops","text":"If something makes the software hang at the same point every time, such as a failing part it waits on or corrupted firmware, the watchdog restarts the phone again and again. That is one cause of boot loops, and it is why a loop alone doesn''t tell you which part has failed."},{"type":"heading","text":"Peripheral resets"},{"type":"list","items":["Many peripherals, such as display, touch, camera and radio sections, have their own reset line, often controlled by the SoC.","The driver holds the peripheral in reset, then releases it once its power and clock are ready, and starts talking to it.","A peripheral stuck in reset doesn''t respond, so the OS may report it as missing even though the part itself may be fine."]},{"type":"callout","tone":"tip","title":"Forced restart","text":"Many phones force a restart when the power key (or a key combination) is held for a long time. This is usually handled by the PMIC, so it can work even when the software has frozen. The exact keys and timing vary by model."}]'::jsonb),
  ('clocks/diagnosing-clock-faults', 'clocks', 'diagnosing-clock-faults', 5, 'Diagnosing clock and reset faults', 'A careful approach to suspected clock and reset faults, and the limits of what a multimeter can tell you.', 12, 'advanced', 'published', array['Order checks so supplies are ruled out before clocks and reset', 'Explain what a multimeter can and can''t tell you about a clock', 'Avoid common mistakes when probing clock circuits']::text[], '[{"type":"text","text":"Clock and reset faults are easy to suspect and hard to prove. A missing clock, a stuck reset and a missing supply can all leave a board doing nothing. Work in order, so each check rules something out."},{"type":"heading","text":"A sensible order"},{"type":"list","ordered":true,"items":["Confirm the symptom: watch the current pattern on a bench power supply and note exactly what the phone does.","Rule out supplies first. Clock chips and the chips that drive crystals need their own supplies, and resets often wait for rails. Check the relevant rails against the schematic.","Inspect the clock parts: look closely for cracked crystals (common after drops), corrosion, liquid residue, and damaged or missing load capacitors.","Check the reset line''s state against the schematic, before and during the power-on attempt.","Check the clock itself, ideally with an oscilloscope."]},{"type":"diagram","diagram":"clock-fault-flow","caption":"The same order as a flow. Each step either rules something out or tells you where to look next. Never jump to replacing a part before the supplies are confirmed."},{"type":"heading","text":"What a multimeter can and can''t tell you"},{"type":"list","items":["Can: whether the supply to an oscillator or driving chip is present.","Can: the steady state of a reset line (held or released), compared with what the schematic says it should be.","Can: resistance or diode-mode readings to compare with a known-good board of the same model, which may reveal a short on a clock line or a damaged load capacitor.","Can''t: confirm a clock is running at the right frequency. A DC voltage reading on a clock line is only an average and doesn''t prove oscillation."]},{"type":"callout","tone":"caution","title":"Probing can stop a crystal","text":"A crystal circuit is delicate. A standard passive probe, even set to 10×, adds about 10 to 15 pF, and that can shift or stop the oscillation. Then a working clock looks dead, or a marginal one appears to work. Measure at a buffered clock output where the schematic has one. On the crystal pins themselves, use a low-capacitance active probe. With only a passive probe, a flat line on a crystal pin proves nothing.","claims":["C-0003"]},{"type":"example","title":"Example reasoning: a dead phone after a drop","steps":["The phone draws a little current briefly when the power key is pressed, then drops back.","The main rails that should be present at this stage are checked against the schematic and are present.","Under magnification, the crystal near the PMIC has a crack in its casing.","The crack makes the crystal a strong suspect, but not a proven cause. Replace it with a part of the same specification from the schematic or parts list, then retest. Confirm the fix with a full power-on, not just a change in the current pattern."],"note":"Fictional example to show the reasoning. Readings are described in words, not values, because they depend on the specific board."},{"type":"callout","tone":"key","title":"Replacing a crystal","text":"Use the exact frequency and specification from the schematic or parts list. Crystals can be damaged by too much heat, so follow the part''s soldering guidance. A replacement that looks the same but has a different frequency or load capacitance may not work, or may work badly.","claims":["C-0004","C-0005"]},{"type":"explorer","blockId":"clock","text":"Review the clock and reset block in the Chipset Explorer: its symptoms and diagnostic approach."}]'::jsonb),
  ('memory/lpddr-basics', 'memory', 'lpddr-basics', 1, 'LPDDR RAM basics', 'What RAM does during boot and while running.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
